pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address player, bool winFirst, bool winSecond) public {
        // We'll simulate two plays, tracking wins
        vm.deal(player, 20); // enough for two tickets
        vm.prank(player);

        // Use block difficulty to force win/loss: we can't control randomness, so we accept any outcome.
        // The rule must hold regardless of randomness, so we just observe the pot after each call and compare with expected.
        // Instead, we'll use a different approach: we call play once, record winCount, then call again and check.
        // But the rule is about the relationship between pot and number of wins.
        // We can track wins by checking if pot drops to 0 after a win.

        // Actually, we need a measurable rule. Let's use a simpler approach:
        // The property is: after any number of play() calls, pot is either 0 or exactly 9 * (number of wins).
        // We'll measure wins by how many times pot was >0 after a win and then reset to 0.
        // But that's complex. Simpler: we can assert that pot is always either 0 or exactly 9 (one win) or 18 (two wins), etc.

        // Since we can only call play() and observe pot, we'll call it twice and check invariants.
        // First call:
        (bool ok1, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        assertTrue(ok1);

        uint potAfterFirst = c.pot();
        // If no win: pot == 10 (reference) or 10 (bug) — both give 10, but bug only has the last call's value.
        // If win: pot == 0 after paying out.
        // The buggy version: pot = msg.value = 10, then if win, pot = 0; if loss, pot = 10.
        // So after one call: reference pot is 10 (loss) or 0 (win); bug pot is 10 (loss) or 0 (win) — same! Need two calls.

        // Second call:
        (bool ok2, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        assertTrue(ok2);

        uint potAfterSecond = c.pot();

        // Reference: after two losses: pot = 20; after one win, one loss: pot = 10; after two wins: pot = 0.
        // Bug: after two losses: pot = 10 (overwritten each time); after win then loss: pot = 10; after loss then win: pot = 10; after two wins: pot = 0.
        // So reference can have pot = 20, bug cannot. Thus rule: pot is never 20 after two plays.

        assertTrue(potAfterSecond < 20, "Pot should not reach 20 after two plays");
    }
}

