pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address player) public {
        vm.assume(player != address(0) && player != c.bank());

        // Record initial balances
        uint256 bankBefore = c.bank().balance;
        uint256 playerBefore = address(player).balance;

        // Give player enough ETH
        vm.deal(player, 10 ether);
        vm.prank(player);

        // Drive the contract - call play()
        (bool success,) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        // Only check on successful calls (random == 0 path)
        if (success) {
            uint256 potAfter = c.pot();
            // If pot is zero, it means we had a winning play
            if (potAfter == 0) {
                uint256 bankAfter = c.bank().balance;
                uint256 playerAfter = address(player).balance;
                uint256 totalTransfer = (bankAfter - bankBefore) + (playerAfter - playerBefore);
                assertTrue(totalTransfer == 10, "Total transferred should equal TICKET_AMOUNT");
            }
        }
    }
}

