pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 val) public {
        // only fuzz over valid ticket amounts (TICKET_AMOUNT = 10 wei)
        vm.assume(val == 10);
        // track pot before call
        uint potBefore = c.pot();
        // make the call with msg.value = val
        (bool ok,) = address(c).call{value: val}(abi.encodeWithSignature("play()"));
        // get pot after call
        uint potAfter = c.pot();
        // General rule: after a play() call, pot must be either 0 (winner case) or (potBefore + val) (no winner case)
        // In the reference, if random != 0, pot remains potBefore + val (the pot is unchanged except the deposit)
        // If random == 0, pot is set to 0 after paying.
        assertTrue(potAfter == 0 || potAfter == potBefore + val);
    }
}

