pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // We need to control the block timestamp and difficulty to ensure a deterministic outcome
        vm.assume(seed > 0); // Avoid trivial case
        vm.warp(seed);
        vm.difficulty(seed);

        address player = address(0x1234);
        vm.deal(player, 10 ether);

        // Measure player's balance before call
        uint256 balanceBefore = player.balance;

        // Perform the call
        vm.prank(player);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        if (success) {
            uint256 potAfter = c.pot();
            // The rule: if the call succeeded, the pot must be zero (since the correct contract
            // pays out all funds when random==0, and if random!=0, the contract should still have
            // no funds because the caller deposited 10 but no payout; with %2, random can only be 0 or 1)
            // Actually, re-express: With the correct modulo 2, after a successful call the pot is always 0
            // because if random==0, pot is set to 0 after payout; if random==1, the contract never pays out
            // but the pot is left as 10, so the previous rules were wrong.
            // Let's instead check: For reference, the play() function either pays out (random==0) setting pot=0
            // or does nothing (random==1) leaving pot=10. So the pot can be 10 after a successful call.
            // The mutant changes %2 to %3, so random can be 0,1,2, and only random==0 triggers payout.
            // So the rule: After a successful call, the pot is either 0 (if random triggers payout)
            // or 10 (if not). But with the bug, random is computed modulo 3, so the probability changes.
            // We need a deterministic rule: Compute expected random using block.timestamp and block.difficulty,
            // then assert that pot matches the expected behavior.
            uint256 expectedRandom = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (expectedRandom == 0) {
                assertTrue(potAfter == 0, "Pot should be zero after payout");
            } else {
                assertTrue(potAfter == 10, "Pot should be 10 when no payout");
            }
        } else {
            // If call reverts, we don't care; just assert something always true
            assertTrue(true);
        }
    }
}

